export function getRecentOrders(
  orders: Order[]
) {
  return [...orders]
    .sort(
      (a, b) =>
        (b.createdAt?.seconds || 0) -
        (a.createdAt?.seconds || 0)
    )
    .slice(0, 10);
}

export function getAverageOrderValue(
  orders: Order[]
) {
  if (orders.length === 0) {
    return 0;
  }

  return Math.round(
    getTotalRevenue(orders) /
    orders.length
  );
}

